MQL:
db.country.aggregate([
  { $match: { Continent: "Europe" } },
  { $unwind: { path: "$cities", preserveNullAndEmptyArrays: false } },
  { $group: {
      _id: "$_id",
      Name: { $first: "$Name" },
      total_cities: { $sum: { $cond: [{ $ne: ["$cities.Population", null] }, 1, 0] } },
      big_cities: { $sum: { $cond: [{ $gt: ["$cities.Population", 1000000] }, 1, 0] } }
  } },
  { $project: {
      _id: 0,
      Name: 1,
      pct: { $cond: [
        { $gt: ["$total_cities", 0] },
        { $divide: ["$big_cities", "$total_cities"] },
        0
      ] }
  } },
  { $match: { pct: { $gt: 0.3 } } }
])
